export const source = "'use client';\n\nimport { type FormEvent, useState } from 'react';\n\nimport { Button } from '@/components/button/button';\nimport {\n  Dialog,\n  DialogBody,\n  DialogClose,\n  DialogContent,\n  DialogDescription,\n  DialogFooter,\n  DialogHeader,\n  DialogTitle,\n  DialogTrigger,\n} from '@/components/dialog/dialog';\nimport { Input } from '@/components/input/input';\nimport { Label } from '@/components/label/label';\n\nexport default function DialogWithForm() {\n  const [open, setOpen] = useState(false);\n  const [name, setName] = useState('Ada Lovelace');\n\n  function handleSubmit(event: FormEvent<HTMLFormElement>) {\n    event.preventDefault();\n    const data = new FormData(event.currentTarget);\n    setName(String(data.get('name')));\n    setOpen(false);\n  }\n\n  return (\n    <div className=\"nx:flex nx:flex-col nx:items-center nx:gap-3\">\n      <Dialog open={open} onOpenChange={setOpen}>\n        <DialogTrigger asChild>\n          <Button variant=\"outline\">Edit profile</Button>\n        </DialogTrigger>\n        <DialogContent>\n          <DialogHeader>\n            <DialogTitle>Edit profile</DialogTitle>\n            <DialogDescription>\n              Change how your name appears to teammates.\n            </DialogDescription>\n          </DialogHeader>\n          <DialogBody>\n            <form\n              id=\"dialog-with-form\"\n              className=\"nx:grid nx:gap-1.5\"\n              onSubmit={handleSubmit}\n            >\n              <Label htmlFor=\"dialog-with-form-name\">Display name</Label>\n              <Input\n                id=\"dialog-with-form-name\"\n                name=\"name\"\n                defaultValue={name}\n                required\n              />\n            </form>\n          </DialogBody>\n          <DialogFooter>\n            <DialogClose asChild>\n              <Button variant=\"outline\">Cancel</Button>\n            </DialogClose>\n            <Button type=\"submit\" form=\"dialog-with-form\">\n              Save changes\n            </Button>\n          </DialogFooter>\n        </DialogContent>\n      </Dialog>\n      <p className=\"nx:typography-body-default nx:text-muted-foreground\">\n        Display name: {name}\n      </p>\n    </div>\n  );\n}\n";
